import {nightCameraFrame} from './night-camera-frame.js';
import * as THREE from 'three';import {PLAZA} from './layout.js';
const keys=['left','right','top','bottom','near','far','zoom'],smooth=t=>t*t*(3-2*t),COVER_BEARING=110*Math.PI/180;
/** A borrowed view with exact source restoration. Opposed bearings switch only
 * behind a fully opaque, host-owned world cover; small turns keep interpolation. */
export function createPlazaCamera(source,{reduced=false,getReturnViewport=()=>null,getReturnCamera=()=>source,forceCovered=false}={}){
 const camera=source.clone();let phase='idle',elapsed=0,start=null,destination=null,width=1,height=1,duration=.8,covered=false,recover=false,coverStart=0,context='source';
 const read=c=>({position:c.position.clone(),quaternion:c.quaternion.clone(),...Object.fromEntries(keys.map(k=>[k,c[k]]))});
 const progress=()=>Math.min(1,elapsed/duration);
 const coverOpacity=()=>{if(!covered)return 0;const p=progress();if(recover)return coverStart*(1-smooth(p));if(p<.35)return coverStart+(1-coverStart)*smooth(p/.35);if(p<=.65)return 1;return 1-smooth((p-.65)/.35);};
 function sourceFrame(entry=false){const f=read(entry?source:getReturnCamera(width,height)??source),r=getReturnViewport();if(!r||r.width<=0||r.height<=0)return f;const z=f.zoom,cx=(f.left+f.right)/2,cy=(f.top+f.bottom)/2,sx=(f.right-f.left)/z,sy=(f.top-f.bottom)/z,left=cx-sx/2-r.x/r.width*sx,right=cx-sx/2+(width-r.x)/r.width*sx,top=cy+sy/2+r.y/r.height*sy,bottom=cy+sy/2-(height-r.y)/r.height*sy,nx=(left+right)/2,ny=(top+bottom)/2;return {...f,left:nx-(right-left)*z/2,right:nx+(right-left)*z/2,top:ny+(top-bottom)*z/2,bottom:ny-(top-bottom)*z/2};}
 function apply(f){camera.position.copy(f.position);camera.quaternion.copy(f.quaternion);for(const k of keys)camera[k]=f[k];camera.updateProjectionMatrix();}
 function frame(){const c=source.clone(),f=nightCameraFrame(PLAZA,width,height);c.position.fromArray(f.position);c.lookAt(...f.target);for(const k of keys)c[k]=f[k];c.updateProjectionMatrix();return read(c);}
 function begin(next,to,{allowCover=true}={}){const oldOpacity=coverOpacity(),oldContext=context;phase=next;elapsed=0;start=read(camera);destination=to;const angle=start.quaternion.angleTo(to.quaternion);recover=next==='exiting'&&oldContext==='source'&&angle<.001&&start.position.distanceTo(to.position)<.01;covered=recover||(allowCover&&(angle>COVER_BEARING||(reduced&&angle>10*Math.PI/180)||forceCovered));coverStart=oldOpacity;duration=recover?.25:covered?(reduced?.35:1.2):Math.max(reduced?.45:.8,angle*1.5/(65*Math.PI/180),start.position.distanceTo(to.position)*1.5/20);context=recover?'source':covered?(next==='exiting'?'show':'source'):'show';}
 function interpolate(t){camera.position.lerpVectors(start.position,destination.position,t);camera.quaternion.slerpQuaternions(start.quaternion,destination.quaternion,t);for(const k of keys)camera[k]=start[k]+(destination[k]-start[k])*t;camera.updateProjectionMatrix();}
 return {camera,get active(){return phase!=='idle';},get phase(){return phase;},get progress(){return progress();},get covered(){return covered;},get coverOpacity(){return coverOpacity();},get context(){return context;},enter(w,h){width=w;height=h;camera.copy(source);apply(sourceFrame(true));context='source';begin('entering',frame());},fit(w,h){if(!Number.isFinite(w)||!Number.isFinite(h)||w<=0||h<=0)return;width=w;height=h;if(covered&&recover){start=sourceFrame();destination=start;apply(start);return;}if(covered&&(phase==='entering'||phase==='exiting')){if(phase==='entering'){start=sourceFrame();destination=frame();}else{start=frame();destination=sourceFrame();}apply(context==='source'?(phase==='entering'?start:destination):(phase==='entering'?destination:start));return;}if(phase==='active'||phase==='reframing')begin('reframing',frame(),{allowCover:false});else if(phase==='entering'){start=read(camera);destination=frame();elapsed=0;}else if(phase==='exiting')begin('exiting',sourceFrame());},exit(){if(phase==='idle'||phase==='exiting')return;begin('exiting',sourceFrame());},tick(dt){if(phase==='idle'||phase==='active'||!Number.isFinite(dt)||dt<=0)return;elapsed+=Math.min(.1,dt);const p=progress();if(covered&&!recover){if(p<.5)apply(start);else{apply(destination);context=phase==='exiting'?'source':'show';}}else interpolate(smooth(p));if(p===1){const exiting=phase==='exiting';phase=exiting?'idle':'active';context=exiting?'source':'show';covered=false;recover=false;}},dispose(){phase='idle';covered=false;recover=false;context='source';}};
}
